    \draw (-0.06,\b) -- (0.06,\b);
    \node[left=4pt] at (0,\b) {$\b$};
}


\foreach \k/\b in {1/1,2/4,3/5,4/6,5/4}
    \draw[gray!60,densely dotted] (\k,0) -- (\k,\b);


\draw[blue!70!black,thick]
    (0,0) -- (2,4) -- (4,6) -- (5,4);


\node[blue!70!black,above left] at (1.7,2.75)
    {$\alpha_1=10^{-2}$};
\node[blue!70!black,above left] at (3,5)
    {$\alpha_2=10^{-1}$};
\node[blue!70!black,above right] at (4.5,5)
    {$\alpha_3=10^2$};


\foreach \k/\b in {0/0,2/4,4/6,5/4}
